import hashlib,importlib.util,json,os,random,statistics,subprocess
from pathlib import Path
ROOT=Path.cwd();HERE=ROOT/'.profile-cache/source-order-profile'
spec=importlib.util.spec_from_file_location('base',ROOT/'benchmarks/bootstrap/measure.py');BASE=importlib.util.module_from_spec(spec);spec.loader.exec_module(BASE)
os.sched_setaffinity(0,{4})
record=json.load(open(ROOT/'.profile-cache/source-order-final.json'))
source=Path(record['commands']['ordinary-8000']['source-order-c-output'][1])
original_library=Path(record['inputs']['ordinary-8000']['native_library']['path'])
# Keep root and library path byte lengths equal between treatments.
commands={}
for label,library in [('baseline','baseline.plugin'),('candidate','no-interposition.plugin')]:
 target=HERE/(label+'.rmd')
 text=source.read_text().replace(os.path.relpath(original_library,source.parent),str(HERE/library))
 # All input paths in the original root are relative to its original directory.
 for path in ['api/rmd0_stage.rmd','stages/c/api.rmd','stages/c/build.rmd']:
  text=text.replace(os.path.relpath(ROOT/path,source.parent),str(ROOT/path))
 workload=Path(record['inputs']['ordinary-8000']['sources']['rmd']['path'])
 text=text.replace(os.path.relpath(workload,source.parent),str(workload))
 target.write_text(text)
 commands[label]=[str(ROOT/'build/rmd'),str(target),'--library','--emit-c','--symbols','/dev/null']
commands['gcc']=record['commands']['ordinary-8000']['gcc-original-syntax']
paths=[ROOT/'build/rmd',HERE/'baseline.plugin',HERE/'no-interposition.plugin',HERE/'baseline.rmd',HERE/'candidate.rmd',Path(__file__)]
def info(p):return {'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}
hashes=[info(p) for p in paths]
outputs=[]
for key in ('baseline','candidate'):
 response=HERE/(key+'.rsp');command=list(commands[key]);command[-1]=str(response)
 p=BASE.run_process(command,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 if p.returncode or p.stderr:raise RuntimeError((command,p.returncode,p.stderr))
 outputs.append((hashlib.sha256(p.stdout).hexdigest(),hashlib.sha256(response.read_bytes()).hexdigest(),len(p.stdout)))
if outputs[0]!=outputs[1]:raise RuntimeError('candidate output differs')
r={'commands':commands,'inputs':hashes,'output_identity':outputs,'cpu':4,'rounds':25,'warmup':1,'seed':202610016,'samples':[],'build':json.load(open(HERE/'candidate-build.json'))}
for c in commands.values():BASE.measure(c)
rng=random.Random(r['seed'])
for i in range(25):
 order=list(commands);rng.shuffle(order)
 for k in order:r['samples'].append({'round':i,'endpoint':k,'wall_ns':BASE.measure(commands[k])})
if hashes!=[info(p) for p in paths]:raise RuntimeError('input changed')
rows=[{x['endpoint']:x['wall_ns'] for x in r['samples'] if x['round']==i} for i in range(25)]
med={k:statistics.median(x[k] for x in rows) for k in commands}
r['median_ms']={k:v/1e6 for k,v in med.items()};r['comparisons']={}
for a,b in [('candidate','baseline'),('candidate','gcc'),('baseline','gcc')]:
 rng=random.Random(str(r['seed'])+a+b);values=[]
 for _ in range(10000):
  selection=rng.choices(rows,k=len(rows));values.append(statistics.median(x[a] for x in selection)/statistics.median(x[b] for x in selection))
 values.sort();r['comparisons'][a+'/'+b]={'ratio':med[a]/med[b],'paired_bootstrap_95_ci':[BASE.percentile(values,.025),BASE.percentile(values,.975)]}
(HERE/'comparison.json').write_text(json.dumps(r,indent=2)+'\n')
print(json.dumps({'median_ms':r['median_ms'],'comparisons':r['comparisons']},indent=2))

